import React, { useState } from "react";

const AttendanceDashboard = () => {
  const [image, setImage] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [students, setStudents] = useState([]); // For dynamic table

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImage(file);
    setPreviewUrl(URL.createObjectURL(file));
  };

  const handleUpload = async () => {
    if (!image) return alert("Please select an image first.");

    const formData = new FormData();
    formData.append("image", image);

    try {
      const response = await fetch("http://localhost:5000/api/students/mark", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      // Safety check
      if (!data.result || !data.result.includes("Detected:")) {
        alert("No faces detected.");
        return;
      }

      const detectedNames = data.result
        .split(/Detected:\s*/g)
        .slice(1)
        .map((line) => {
          const name = line.split("\n")[0].trim();
          return { name, rollNo: "Unknown", status: "Present" };
        });

      const namesForAlert = detectedNames.map((s) => s.name).join(", ");
      alert(`Detected students: ${namesForAlert}`);
      setStudents(detectedNames); // Set for table

      console.log("Python Output:", data.result);
    } catch (err) {
      console.error("Upload failed:", err);
      alert("Failed to upload and mark attendance.");
    }
  };

  return (
    <div style={{ padding: "2rem", backgroundColor: "#f7f7f7", minHeight: "100vh" }}>
      <h1 style={{ fontSize: "2rem", fontWeight: "bold", textAlign: "center" }}>
        📸 Smart Attendance Dashboard
      </h1>

      <div style={{ maxWidth: "500px", margin: "2rem auto", padding: "1rem", backgroundColor: "#fff", borderRadius: "12px", boxShadow: "0 2px 8px rgba(0,0,0,0.1)" }}>
        <h2 style={{ fontSize: "1.2rem", marginBottom: "1rem" }}>Upload Group Photo</h2>
        <input type="file" accept="image/*" onChange={handleImageChange} style={{ marginBottom: "1rem" }} />

        {previewUrl && <img src={previewUrl} alt="Preview" style={{ maxHeight: "300px", width: "100%", borderRadius: "8px", marginBottom: "1rem" }} />}

        <button onClick={handleUpload} style={{ width: "100%", padding: "10px", backgroundColor: "#4f46e5", color: "white", border: "none", borderRadius: "8px", fontWeight: "bold" }}>
          Upload & Mark Attendance
        </button>
      </div>

      <div style={{ maxWidth: "800px", margin: "2rem auto", backgroundColor: "#fff", padding: "1rem", borderRadius: "12px", boxShadow: "0 2px 8px rgba(0,0,0,0.1)" }}>
        <h2 style={{ fontSize: "1.2rem", marginBottom: "1rem" }}>🎓 Student Attendance List</h2>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead style={{ backgroundColor: "#eee" }}>
            <tr>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Name</th>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Roll No</th>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {students.length === 0 ? (
              <tr>
                <td colSpan="3" style={{ textAlign: "center", padding: "8px" }}>No students marked yet.</td>
              </tr>
            ) : (
              students.map((student, index) => (
                <tr key={index}>
                  <td style={{ border: "1px solid #ccc", padding: "8px" }}>{student.name}</td>
                  <td style={{ border: "1px solid #ccc", padding: "8px" }}>{student.rollNo}</td>
                  <td style={{ border: "1px solid #ccc", padding: "8px", color: "green", fontWeight: "bold" }}>{student.status}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AttendanceDashboard;
